#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=6

banner "Finance Assistant staging bootstrap"

REPOSITORY="hankgalt/ai_finance_assitant"
PROJECT_ID="comfforts-369117"
REGION="us-west1"
BOOTSTRAP_BUCKET="${PROJECT_ID}-aifa-tf-bootstrap"
STAGING_BUCKET="${PROJECT_ID}-aifa-tf-staging"
REPO_ROOT=$(cd "$(dirname "${BASH_SOURCE[0]}")/../../.." && pwd)
BOOTSTRAP_ROOT="$REPO_ROOT/infrastructure/terraform/bootstrap"
SHARED_ROOT="$REPO_ROOT/infrastructure/terraform/shared"
STAGING_ROOT="$REPO_ROOT/infrastructure/terraform/environments/staging"

# ── Stage 1: local identity and tool preflight ─────────────────────────────
stage "Verify local identity and tools"
say "This stage performs read-only checks and accepts no credential payload."
for tool in gcloud terraform gh jq; do
  command -v "$tool" >/dev/null 2>&1 || { warn "$tool is not available on PATH"; exit 1; }
done
ACTIVE_ACCOUNT=$(gcloud auth list --filter=status:ACTIVE --format='value(account)')
ACTIVE_PROJECT=$(gcloud config get-value project 2>/dev/null)
[[ "$ACTIVE_ACCOUNT" == "vtalwar.w@comfforts.com" ]] || { warn "unexpected active account: $ACTIVE_ACCOUNT"; exit 1; }
[[ "$ACTIVE_PROJECT" == "$PROJECT_ID" ]] || { warn "unexpected active project: $ACTIVE_PROJECT"; exit 1; }
gh auth status >/dev/null
terraform version
say "Verified $ACTIVE_ACCOUNT on $PROJECT_ID."
pause "Continue to the remote-state bootstrap?"

# ── Stage 2: bootstrap remote state ────────────────────────────────────────
stage "Bootstrap protected Terraform state"
say "The first bucket is created once with gcloud, then immediately imported under Terraform ownership."
if ! gcloud storage buckets describe "gs://$BOOTSTRAP_BUCKET" >/dev/null 2>&1; then
  confirm "Create gs://$BOOTSTRAP_BUCKET with versioning, soft delete, and public-access prevention?" || exit 1
  gcloud storage buckets create "gs://$BOOTSTRAP_BUCKET" \
    --project="$PROJECT_ID" \
    --location="${REGION^^}" \
    --uniform-bucket-level-access \
    --public-access-prevention \
    --soft-delete-duration=7d
  gcloud storage buckets update "gs://$BOOTSTRAP_BUCKET" --versioning
fi
terraform -chdir="$BOOTSTRAP_ROOT" init -reconfigure \
  -backend-config="bucket=$BOOTSTRAP_BUCKET" \
  -backend-config="prefix=bootstrap"
if ! terraform -chdir="$BOOTSTRAP_ROOT" state show 'google_storage_bucket.terraform_state["bootstrap"]' >/dev/null 2>&1; then
  terraform -chdir="$BOOTSTRAP_ROOT" import \
    'google_storage_bucket.terraform_state["bootstrap"]' "$BOOTSTRAP_BUCKET"
fi
terraform -chdir="$BOOTSTRAP_ROOT" plan -lock-timeout=5m -out=bootstrap.tfplan
confirm "Apply only the reviewed state-bucket plan shown above?" || exit 1
terraform -chdir="$BOOTSTRAP_ROOT" apply bootstrap.tfplan

# ── Stage 3: shared delivery foundation ───────────────────────────────────
stage "Apply shared APIs, budget, registry, and WIF"
BILLING_ACCOUNT_NAME=$(gcloud billing projects describe "$PROJECT_ID" --format='value(billingAccountName)')
BILLING_ACCOUNT_ID="${BILLING_ACCOUNT_NAME##*/}"
terraform -chdir="$SHARED_ROOT" init -reconfigure \
  -backend-config="bucket=$BOOTSTRAP_BUCKET" \
  -backend-config="prefix=shared"
terraform -chdir="$SHARED_ROOT" plan -lock-timeout=5m \
  -var="billing_account_id=$BILLING_ACCOUNT_ID" \
  -out=shared.tfplan
confirm "Apply the reviewed shared-foundation plan shown above?" || exit 1
terraform -chdir="$SHARED_ROOT" apply shared.tfplan

# ── Stage 4: staging managed-state foundation ─────────────────────────────
stage "Apply the staging managed-state foundation"
warn "This creates the approved billable single-zone db-f1-micro Cloud SQL instance."
terraform -chdir="$STAGING_ROOT" init -reconfigure \
  -backend-config="bucket=$STAGING_BUCKET" \
  -backend-config="prefix=foundation"
terraform -chdir="$STAGING_ROOT" plan -lock-timeout=5m -out=staging.tfplan
confirm "Apply the reviewed staging plan, including Cloud SQL?" || exit 1
terraform -chdir="$STAGING_ROOT" apply staging.tfplan

# ── Stage 5: protected GitHub environments and non-secret variables ───────
stage "Activate protected GitHub environments"
say "GitHub receives only project, provider, and service-account identifiers."
ENVIRONMENT_PAYLOAD=$(mktemp)
printf '%s\n' '{"wait_timer":0,"prevent_self_review":false,"reviewers":[{"type":"User","id":2118128}],"deployment_branch_policy":{"protected_branches":false,"custom_branch_policies":true}}' > "$ENVIRONMENT_PAYLOAD"
for environment in staging production; do
  gh api --method PUT "repos/$REPOSITORY/environments/$environment" --input "$ENVIRONMENT_PAYLOAD" >/dev/null
  if ! gh api "repos/$REPOSITORY/environments/$environment/deployment-branch-policies" \
    --jq '.branch_policies[].name' | grep -qx main; then
    gh api --method POST "repos/$REPOSITORY/environments/$environment/deployment-branch-policies" \
      -f name=main >/dev/null
  fi
done
rm -f "$ENVIRONMENT_PAYLOAD"

STAGING_PROVIDER=$(terraform -chdir="$SHARED_ROOT" output -raw staging_workload_identity_provider)
STAGING_SERVICE_ACCOUNT=$(terraform -chdir="$SHARED_ROOT" output -raw staging_deploy_service_account)
PRODUCTION_PROVIDER=$(terraform -chdir="$SHARED_ROOT" output -raw production_workload_identity_provider)
PRODUCTION_SERVICE_ACCOUNT=$(terraform -chdir="$SHARED_ROOT" output -raw production_deploy_service_account)

for environment in staging production; do
  gh variable set GCP_PROJECT_ID --repo "$REPOSITORY" --env "$environment" --body "$PROJECT_ID"
done
gh variable set GCP_WORKLOAD_IDENTITY_PROVIDER --repo "$REPOSITORY" --env staging --body "$STAGING_PROVIDER"
gh variable set GCP_DEPLOY_SERVICE_ACCOUNT --repo "$REPOSITORY" --env staging --body "$STAGING_SERVICE_ACCOUNT"
gh variable set GCP_WORKLOAD_IDENTITY_PROVIDER --repo "$REPOSITORY" --env production --body "$PRODUCTION_PROVIDER"
gh variable set GCP_DEPLOY_SERVICE_ACCOUNT --repo "$REPOSITORY" --env production --body "$PRODUCTION_SERVICE_ACCOUNT"
say "Protected environments and non-secret identity variables are configured."

# ── Stage 6: short-lived identity smoke ───────────────────────────────────
stage "Run short-lived cloud identity smoke"
say "Both environments execute only gcloud projects describe through GitHub OIDC."
confirm "Dispatch the staging and production identity-smoke workflows from main?" || exit 1
gh workflow run cloud-identity-smoke.yml --repo "$REPOSITORY" --ref main -f environment=staging
gh workflow run cloud-identity-smoke.yml --repo "$REPOSITORY" --ref main -f environment=production
open_url "https://github.com/$REPOSITORY/actions/workflows/cloud-identity-smoke.yml"
step "Wait for both protected-environment runs to complete successfully."
pause "Press Enter after both runs pass, or Ctrl-C to stop and investigate."

finish
}

run_wizard "$@"; exit
